#include <stdio.h>
#include <stdlib.h>
/* ex05：FCFS 磁盘调度——按请求到达顺序服务
 * 优点：公平、无饥饿；缺点：磁头来回跑，总寻道距离可能极大。
 * 本程序用同一组请求对比 FCFS 与 SSTF 的总寻道距离。*/
int main(void) {
    int req[] = {98, 183, 37, 122, 14, 124, 65, 67};
    int n = (int)(sizeof(req) / sizeof(req[0]));
    int head = 53;

    int total = 0, cur = head;
    printf("初始磁头=%d\n", head);
    printf("%-8s %-10s %s\n", "请求", "移动距离", "累计");
    for (int i = 0; i < n; i++) {
        int d = abs(req[i] - cur);
        total += d;
        cur = req[i];
        printf("%-8d %-10d %d\n", req[i], d, total);
    }
    printf("FCFS 总寻道距离 = %d 个磁道\n", total);
    printf("若每移动 1 道耗时 0.2ms，总寻道时间 = %.1f ms\n", total * 0.2);
    return 0;
}
